// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 seed) public {
        address player = address(0x123);
        vm.deal(player, 100 ether);
        vm.prank(player);
        c.play{value: 10}();
        uint256 bankBalanceBefore = address(c.bank()).balance;
        vm.warp(seed % 1_000_000_000);
        vm.roll(seed % 1_000_000);
        vm.prank(player);
        try c.play{value: 10}() {} catch {}
        assertTrue(
            c.pot() != 0 || address(c.bank()).balance == bankBalanceBefore + 1
        );
    }
}
